const DexText = {"387": "Made from soil, the shell on its back hardens when it drinks water. It lives along lakes.", "388": "A Grotle that lives in the forest is said to have its own secret springwater.", "389": "Ancient people imagined that beneath the ground, a gigantic Torterra dwelled.", "390": "Its fiery rear end is fueled by gas made in its belly. Even rain can't extinguish the fire.", "391": "To intimidate attackers, it stretches the fire on its tail to make itself appear bigger.", "392": "It tosses its enemies around with agility. It uses all its limbs to fight in its own unique style.", "393": "Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.", "394": "Because every Prinplup considers itself to be the most important, they can never form a group.", "395": "It avoids unnecessary disputes, but it will decimate anything that threatens its pride.", "396": "They flock in great numbers. Though small, they flap their wings with great power.", "397": "It lives in forests and fields. Squabbles over territory occur when flocks collide.", "398": "It has a savage nature. It will courageously challenge foes that are much larger.", "399": "With nerves of steel, nothing can perturb it. It is more agile and active than it appears.", "400": "It makes its nest by damming streams with bark and mud. It is known as an industrious worker.", "401": "When its antennae hit each other, it sounds like the music of a xylophone.", "402": "It signals its emotions with its melodies. Scientists are studying these melodic patterns.", "403": "All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded.", "404": "It rests its forelegs on others to communicate with rhythmic electric pulses from its claws.", "405": "It can see clearly through walls to track down its prey and seek its lost young.", "406": "It lives alongside clear ponds. It scatters pollen that induces harsh sneezing and runny noses.", "407": "It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.", "408": "It lived in jungles around 100 million years ago. Its skull is as hard as iron.", "409": "Its powerful headbutt has enough power to shatter even the most durable things upon impact.", "410": "It is outstandingly armored. As a result, it can eat grass and berries without having to fight.", "411": "When attacked, they form a wall with their shield like faces to protect their young.", "412": "If its cloak is broken in battle, it quickly remakes the cloak with materials nearby.", "413": "It is said that a Wormadam that evolves on a cold day will have a thicker cloak.", "414": "It flutters around at night and steals honey from the Combee hive.", "415": "A Pokémon formed by three others. It busily carries sweet floral honey to Vespiquen.", "416": "It raises grubs in the holes in its body. It secretes pheromones to control Combee.", "417": "It's one of the kinds of Pokémon with electric cheek pouches. It shoots charges from its tail.", "418": "It swims by rotating its two tails like a screw. When it dives, its flotation sac collapses.", "419": "It is a common sight around fishing ports. It is known to rescue people and carry off prey.", "420": "The small ball is not only full of nutrients, it is also tasty. Starly try to peck it off.", "421": "It blooms during times of strong sunlight. It tries to make up for everything it endured as a bud.", "422": "Its shape and coloration vary, depending on its habitat.", "423": "When its natural enemy attacks, it oozes purple fluid and escapes.", "424": "It is very difficult to dodge the consecutive strikes of its two tails.", "425": "Stories go that it grabs the hands of small children and drags them away to the afterlife.", "426": "It grabs people and Pokémon and carries them off somewhere. Where do they go? Nobody knows.", "427": "Its ears are always rolled up. They can be forcefully extended to shatter even a large boulder.", "428": "It sheds its fur twice a year. Its winter fur is soft and fluffy.", "429": "It chants incantations. While they usually torment targets, some chants bring happiness.", "430": "Becoming active at night, it is known to swarm with numerous Murkrow in tow.", "431": "With its sharp glare, it puts foes in a mild hypnotic state. It is a very fickle Pokémon.", "432": "To make itself appear intimidatingly beefy, it tightly cinches its waist with its twin tails.", "433": "It emits cries by agitating an orb at the back of its throat. It moves with flouncing hops.", "434": "It sprays a nose-curling, stinky fluid from its rear to repel attackers.", "435": "It sprays a vile-smelling fluid from the tip of its tail to attack. Its range is over 160 feet.", "436": "X-ray photos were taken to check its body structure. Nothing appeared, however.", "437": "Ancient people believed that petitioning Bronzong for rain was the way to make crops grow.", "438": "It prefers arid environments. It leaks water from its eyes to adjust its body's fluid levels.", "439": "It habitually mimics foes. Once mimicked, the foe cannot take its eyes off this Pokémon.", "440": "It loves round white things. It carries an egg-shaped rock in imitation of Chansey.", "441": "Its tongue is just like a human's. As a result, it can cleverly mimic human speech.", "442": "A Pokémon that was formed by 108 spirits. It is bound to a fissure in an Odd Keystone.", "443": "It once lived in the tropics. To avoid the cold, it lives in caves warmed by geothermal heat.", "444": "It loves sparkly things. It seeks treasures in caves and hoards the loot into its nest.", "445": "It flies at speeds equal to a jet fighter plane. It never allows its prey to escape.", "446": "It hides food under its long body hair. However, it forgets it has hidden the food.", "447": "The aura that emanates from its body intensifies to alert others if it is afraid or sad.", "448": "It has the ability to sense the Auras of all things. It understands human speech.", "449": "It lives in arid places. Instead of perspiration, it expels grainy sand from its body.", "450": "Surprisingly quick to anger. It holds its mouth agape as a display of strength.", "451": "It lives in arid lands. It buries itself in sand and lies in wait for unsuspecting prey.", "452": "Its body is encased in a sturdy shell. Its head rotates 180 degrees, eliminating blind spots.", "453": "Inflating its poison sacs, it makes an eerie blubbering sound for intimidation.", "454": "Its knuckle claws secrete a toxin so vile that even a scratch could prove fatal.", "455": "Hanging from branches using its tentacles, it looks like a plant. It awaits prey, mouth wide open.", "456": "The line running down its side can store sunlight. It shines vividly at night.", "457": "Lumineon swimming in the darkness of the deep sea look like stars shining in the night sky.", "458": "Scientists discovered that the distinctive patterns on its back differ by region.", "459": "In the spring, it grows berries with the texture of frozen treats around its belly.", "460": "It blankets wide areas in snow by whipping up blizzards. It is also known as \"The Ice Monster.\"", "461": "It sends signals to others by carving odd patterns in frost-covered trees and ice.", "462": "It evolved from exposure to a special magnetic field. Three units generate magnetism.", "463": "The long tongue is always soggy with slobber. The saliva contains a solvent that causes numbness.", "464": "From holes in its palms, it fires out Geodude. Its carapace can withstand volcanic eruptions.", "465": "Its vines grow so profusely that, in the warm season, you can't even see its eyes.", "466": "As its electric charge amplifies, blue sparks begin to crackle between its horns.", "467": "When launching 3,600 degrees F fireballs, its body takes on a whitish hue from the intense heat.", "468": "It will never appear where there is strife. Its sightings have become rare recently.", "469": "Its jaw power is incredible. It is adept at biting apart foes while flying by at high speed.", "470": "Just like a plant, it uses photosynthesis. As a result, it is always enveloped in clear air.", "471": "It causes small ice crystals to form by lowering the temperature of the surrounding atmosphere.", "472": "It observes prey while hanging inverted from branches. When the chance presents itself, it swoops!", "473": "A frozen one was dug up from soil dating back 10,000 years. It woke up to much amazement.", "474": "Its programming was modified to enable work in alien dimensions. It did not work as planned.", "475": "A master of courtesy and swordsmanship, it fights using extending swords on its elbows.", "476": "It freely controls three small units called Mini-Noses using magnetic force.", "477": "It is said to take lost spirits into its pliant body and guide them home.", "478": "Legends in snowy regions say that a woman who was lost on an icy mountain was reborn as Froslass.", "479": "Its body is composed of plasma. It is known to infiltrate electronic devices and wreak havoc.", "480": "Known as \"The Being of Knowledge.\" It is said that it can wipe out the memory of those who see its eyes.", "481": "Known as \"The Being of Emotion.\" It taught humans the nobility of sorrow, pain, and joy.", "482": "Known as \"The Being of Willpower.\" It sleeps at the bottom of a lake to keep the world in balance.", "483": "A legendary Pokémon of Sinnoh. It is said that time flows when Dialga's heart beats.", "484": "It has the ability to distort space. It is described as a deity in Sinnoh-region mythology.", "485": "It dwells in volcanic caves. It digs in with its cross-shaped feet to crawl on ceilings and walls.", "486": "There is an enduring legend that states this Pokémon towed continents with ropes.", "487": "It was banished for its violence. It silently gazed upon the old world from the Distortion World.", "488": "On nights around the quarter moon, the aurora from its tail extends and undulates beautifully.", "489": "It drifts in warm seas. It always returns to where it was born, no matter how far it may have drifted.", "490": "It is born with a wondrous power that lets it bond with any kind of Pokémon.", "491": "To protect itself, it afflicts those around it with nightmares. However, it means no harm.", "492": "The flowers all over its body burst into bloom if it is lovingly hugged and senses gratitude.", "493": "It is told in mythology that this Pokémon was born before the universe even existed.", "494": "It creates an unlimited supply of energy inside its body, which it shares with those who touch it.", "495": "It is very intelligent and calm. Being exposed to lots of sunlight makes its movements swifter.", "496": "When it gets dirty, its leaves can't be used in photosynthesis, so it always keeps itself clean.", "497": "It can stop its opponents' movements with just a glare. It takes in solar energy and boosts it.", "498": "It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.", "499": "When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.", "500": "It has mastered fast and powerful fighting moves. It grows a beard of fire.", "501": "The scalchop on its stomach isn't just used for battle--it is also used to break open hard berries.", "502": "Strict training is how it learns its flowing double-scalchop technique.", "503": "In the time it takes a foe to blink, it can draw and sheathe the seamitars attached to its front legs.", "504": "Extremely cautious, one of them is always on a lookout, but it won't notice a foe coming from behind.", "505": "Using luminescent matter, it makes its eyes and body glow and stuns attacking opponents.", "506": "Though it is a very brave Pokémon, it's also smart enough to check its foe's strength and avoid battle.", "507": "This very loyal Pokémon helps Trainers, and it also takes care of other Pokémon.", "508": "This extremely wise Pokémon excels at rescuing people stranded at sea or in the mountains.", "509": "They trick people with cuteness, and steal their valuables just to see the looks on their faces.", "510": "Their beautiful form comes from the muscles they have developed. They run silently in the night.", "511": "It shares the leaf on its head with weary-looking Pokémon. These leaves are known to relieve stress.", "512": "It strikes its enemies with a thorn-covered tail. The leaf on its head is bitter.", "513": "Very intelligent, it roasts berries before eating them. It likes to help people.", "514": "It loves sweets because they become energy for the fire burning inside its body.", "515": "The water stored inside the tuft on its head is full of nutrients. It waters plants using its tail.", "516": "The high-pressure water expelled from its tail is so powerful, it can destroy a concrete wall.", "517": "This Pokémon appears before people and Pokémon who are having nightmares and eats those dreams.", "518": "The mist emanating from their foreheads is packed with the dreams of people and Pokémon.", "519": "These Pokémon live in cities. They are accustomed to people. Flocks often gather in parks and plazas.", "520": "It can return to its Trainer's location regardless of the distance separating them.", "521": "Males swing the plumage on their heads to threaten others, but females are better at flying.", "522": "Its mane shines when discharging electricity. It uses flashing manes to communicate with others.", "523": "When this ill-tempered Pokémon runs wild, it shoots lightning from its mane in all directions.", "524": "Its ear is hexagonal in shape. Compressed underground, its body is as hard as steel.", "525": "Because its energy was too great to be contained, the energy leaked and formed orange crystals.", "526": "The solar rays it absorbs are processed in its energy core and fired as a ball of light.", "527": "It emits ultrasonic waves from its nose to learn about its surroundings.", "528": "It shakes its tail vigorously when it emits ultrasonic waves strong enough to reduce concrete to rubble.", "529": "By spinning its body, it can dig straight through the ground at a speed of 30 mph.", "530": "Forming a drill with its steel claws and head, it can cut through a steel plate, no matter the thickness.", "531": "Using the feelers on its ears, it can tell how someone is feeling or when an egg might hatch.", "532": "Always carrying squared logs, they help out with construction. As they grow, they carry bigger logs.", "533": "With strengthened bodies, they skillfully wield steel beams to take down buildings.", "534": "It is thought that Conkeldurr taught humans how to make concrete more than 2,000 years ago.", "535": "They warn others of danger by vibrating their cheeks to create a high-pitched sound.", "536": "It lives in the water and on land. It uses its long, sticky tongue to capture prey.", "537": "By putting power into its bumps, it creates vibrations and increases the power of its punches.", "538": "When it tightens its belt, it becomes stronger. Wild Throh use vines to weave their own belts.", "539": "Desiring the strongest karate chop, they seclude themselves in mountains and train without sleeping.", "540": "Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.", "541": "Preferring dark, damp places, it spends the entire day eating fallen leaves that lie around it.", "542": "It keeps its eggs warm with heat from fermenting leaves.", "543": "Its bite injects a potent poison, enough to paralyze large bird Pokémon that try to prey on it.", "544": "Protected by a hard shell, it spins its body like a wheel and crashes furiously into its enemies.", "545": "Highly aggressive, it uses the claws near its neck to dig into its opponents and poison them.", "546": "When attacked, it escapes by shooting cotton from its body to serve as a decoy to distract the attacker.", "547": "Like the wind, it can slip through any gap, no matter how small. It leaves balls of white fluff behind.", "548": "The leaves on its head are very bitter. Eating one of these leaves is known to refresh a tired body.", "549": "The fragrance of the garland on its head has a relaxing effect, but taking care of it is very difficult.", "550": "Savage, violent Pokémon, red and blue Basculin are always fighting each other over territory.", "551": "They live hidden under hot desert sands in order to keep their body temperature from dropping.", "552": "It buries some of its prey in the sand to use as emergency meals when its hunts are unsuccessful.", "553": "It conceals itself in sandstorms that Flygon whip up and waits patiently for prey to appear.", "554": "When it sleeps, it pulls its limbs into its body and its internal fire goes down to 1,100 degrees F.", "555": "When weakened in battle, it transforms into a stone statue then sharpens its mind and fights mentally.", "556": "Arid regions are their habitat. They move rhythmically, making a sound similar to maracas.", "557": "This Pokémon can easily melt holes in hard rocks with a liquid secreted from its mouth.", "558": "When its boulder is broken in battles for territory, it feels unsure and begins to weaken.", "559": "It immediately headbutts anyone that makes eye contact with it. Its skull is massively thick.", "560": "This Pokémon may be rude, but it takes very good care of its family, its friends, and its turf.", "561": "The guardians of an ancient city, they always fly the same route while keeping watch for invaders.", "562": "Each of them carries a mask that used to be its face when it was human.", "563": "Grave robbers who mistake them for real coffins and get too close end up trapped inside their bodies.", "564": "Restored from a fossil, this Pokémon can dive to depths beyond half a mile.", "565": "Incredible jaw strength enables them to chew up steel beams and rocks along with their prey.", "566": "Restored from a fossil, this ancient bird Pokémon has wings but can't yet fly.", "567": "It runs better than it flies. It takes off into the sky by running at a speed of 25 mph.", "568": "Wanting more garbage, they follow people who litter. They always belch poison gas.", "569": "Consuming garbage makes new kinds of poison gases and liquids inside their bodies.", "570": "It changes so it looks just like its foe, tricks it, and then uses that opportunity to flee.", "571": "Stories say those who tried to catch Zoroark were trapped in an illusion and punished.", "572": "Minccino greet each other by grooming one another thoroughly with their tails.", "573": "Their white fur is coated in a special oil that makes it easy for them to deflect attacks.", "574": "Their ribbonlike feelers increase their psychic power. They are always staring at something.", "575": "According to old tales, it creates friends for itself by controlling sleeping children on starry nights.", "576": "Starry skies thousands of light-years away are visible in the space distorted by their psychic power.", "577": "Because their bodies are enveloped in a special liquid, they can survive in any environment.", "578": "When their two divided brains think the same thoughts, their psychic power is maximized.", "579": "When Reuniclus shake hands, a network forms between their brains, increasing their psychic power.", "580": "When attacked, it uses its feathers to splash water, escaping under cover of the spray.", "581": "Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.", "582": "It feels pleasantly cool when embraced. This Pokémon is treasured by households in warm regions.", "583": "This hearty Pokémon survived the Ice Age. It's incredibly popular in very hot regions.", "584": "If both heads get angry simultaneously, this Pokémon expels a blizzard, burying everything in snow.", "585": "The turning of the seasons changes the color and scent of its fur. People use it to mark the seasons.", "586": "They migrate according to seasons, so some people call Sawsbuck the harbingers of spring.", "587": "They live on treetops and glide using the inside of a cape-like membrane while discharging electricity.", "588": "For some reason they evolve when they receive electrical energy while they are attacking Shelmet.", "589": "Wearing the shell covering they stole from Shelmet, they defend themselves and attack with two lances.", "590": "It lures Pokémon with its pattern that looks just like a Poké Ball then releases poison spores.", "591": "It moves the caps on both arms and does a dance to lure prey. It prefers damp places.", "592": "They paralyze prey with poison, then drag them down to their lairs, five miles below the surface.", "593": "Jellicent is always hanging around fancy cruise ships and tankers, hoping to drag away its prey.", "594": "The special membrane enveloping Alomomola has the ability to heal wounds.", "595": "Joltik that live in cities have learned a technique for sucking electricity from the outlets in houses.", "596": "When attacked, they create an electric barrier by spitting out many electrically charged threads.", "597": "They stick their spikes into cave walls and absorb the minerals they find in the rock.", "598": "By swinging around its three spiky feels and shooting spikes, it can obliterate an opponent.", "599": "Two bodies comprise a fixed pair. They spin around each other to generate energy.", "600": "A mini and big gear comprise its body. If the mini gear it launches at a foe doesn't return, it will die.", "601": "The gear with the red core is rotated at high speed for a rapid energy charge.", "602": "While one alone doesn't have much power, a chain of many Tynamo can be as powerful as lightning.", "603": "This Pokémon has a big appetite. When it spots its prey, it attacks it and paralyzes it with electricity.", "604": "With its sucker mouth, it sucks in prey. Then it uses its fangs to shock the prey with electricity.", "605": "Rumors of its origin are linked to a UFO crash site in the desert 50 years ago.", "606": "It uses psychic power to control an opponent's brain and tamper with its memories.", "607": "Its flame is usually out, but it starts shining when it absorbs life force from people or Pokémon.", "608": "It arrives near the moment of death and steals spirit from the body.", "609": "Being consumed in Chandelure's flame burns up the spirit, leaving the body behind.", "610": "Its large tusks have a tendency to break, but each time they grow back, they grow in harder and sturdier.", "611": "Their tusks can shatter rocks. Territory battles between Fraxure can be intensely violent.", "612": "Their sturdy tusks will stay sharp even if used to cut steel beams. They are covered in hard armor.", "613": "When it is not feeling well, its mucus gets watery and the power of its Ice-type moves decreases.", "614": "It freezes its breath to create fangs and claws of ice. Cold northern areas are its habitat.", "615": "They are born in snow clouds. They use chains made of ice crystals to capture prey.", "616": "When it and Karrablast are together, and both receive electrical stimulation, they both evolve.", "617": "Having removed its heavy shell, it becomes very light and can fight with ninja-like movements.", "618": "When its opponent can't be paralyzed, it contorts itself with unexpected speed and flops away.", "619": "It takes pride in the speed at which it uses moves. What it loses in power, it makes up for in quantity.", "620": "They use the long fur on their arms as a whip to strike their opponents.", "621": "It runs through the narrow tunnels formed by Excadrill and Onix. It uses its sharp claws to catch prey.", "622": "Ancient science fashioned this Pokémon from clay. It's been active for thousands of years.", "623": "Golurk were created to protect people and Pokémon. They run on a mysterious energy.", "624": "Ignoring their injuries, groups attack by sinking the blades that cover their bodies into their prey.", "625": "Bisharp pursues prey in the company of a large group of Pawniard. Then Bisharp finishes off the prey.", "626": "Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt.", "627": "They crush berries with their talons. They bravely stand up to any opponent, no matter how strong it is.", "628": "The more scars they have, the more respect these brave soldiers of the sky get from their peers.", "629": "They tend to guard their posteriors with suitable bones they have found. They pursue weak Pokémon.", "630": "It skillfully arranges the bones of its prey to construct its nest. Most of the bones are Cubone.", "631": "It breathes through a hole in its tail while it burns with an internal fire. Durant is its prey.", "632": "Durant dig nests in mountains. They build their complicated, interconnected tunnels in mazes.", "633": "It tends to bite everything, and it is not a picky eater. Approaching it carelessly is dangerous.", "634": "The two heads do not get along. Whichever head eats more than the other gets to be the leader.", "635": "It responds to movement by attacking. This scary, three-headed Pokémon devours everything in its path!", "636": "It protects itself with flame. Long years ago, people believed Larvesta had a nest on the sun.", "637": "When volcanic ash darkened the atmosphere, Volcarona's fire provided a replacement for the sun.", "638": "It has a body and heart of steel. Its glare is sufficient to make even an unruly Pokémon obey it.", "639": "This Pokémon came to the defense of Pokémon that had lost their homes in a war among humans.", "640": "Legends say this Pokémon confounded opponents with its swift movements.", "641": "In every direction it flies, creating winds so powerful, they blow everything away.", "642": "Countless charred remains mar the landscape of places through which Thundurus has passed.", "643": "When Reshiram's tail flares, the heat energy moves the atmosphere and changes the world's weather.", "644": "This Pokémon appears in legends. In its tail, it has a giant generator that creates electricity.", "645": "Lands visited by Landorus grant bountiful crops. It has been hailed as \"The Guardian of the Fields.\"", "646": "It can produce ultracold air. Its body is frozen.", "647": "It crosses the world, running over the surfaces of oceans and rivers. It appears at scenic waterfronts.", "648": "Many famous songs have been inspired by the melodies that Meloetta plays.", "649": "This ancient bug Pokémon was altered by Team Plasma. They upgraded the cannon on its back.", "650": "Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn't faze it.", "651": "It relies on its sturdy shell to deflect predators' attacks. It counterattacks with its sharp quills.", "652": "When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.", "653": "Eating a twig fills it with energy, and its roomy ears give vent to very hot air.", "654": "With friction from its tail fur, it sets the twig on its tail on fire and launches into battle.", "655": "It gazes into the flame at its branch to achieve a focused state, allowing it to see the future.", "656": "It secretes bubbles from its chest and back. The bubbles reduce the damage it would take when attacked.", "657": "Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute's time.", "658": "It creates throwing stars out of compressed water, that can split metal in two.", "659": "They use their large ears to dig burrows. They will dig the whole night through.", "660": "As powerful as an excavator, its ears can reduce dense bedrock to rubble.", "661": "When it's excited, its temperature can double, spiking hormone production in its body.", "662": "Its speed right after takeoff already puts it in the top speed class of all bird Pokémon.", "663": "When attacking prey, it can reach speeds of up to 310 mph. It finishes its prey off with a colossal kick.", "664": "The powder that covers its body regulates its temperature, so it can live in any region or climate.", "665": "The beaks of birds can't begin to scratch its stalwart body. To defend itself, it spews powder.", "666": "The colorful patterns on this Pokémon's wings depend on the climate and topography of its habitat.", "667": "The stronger the opponent it faces, the more heat and power flow through its body.", "668": "The male with the largest mane of fire is the leader of the pride.", "669": "It draws and controls the hidden power of flowers. The flower it holds is most likely part of its body.", "670": "When the flowers of a well-tended flower bed bloom, it appears and celebrates with an elegant dance.", "671": "Its life can span several hundred years. It's said to devote its entire life to protecting gardens.", "672": "Thought to be one of the first Pokémon to live in harmony with humans, it has a placid disposition.", "673": "They inhabit mountainous regions. The leader of the herd is decided by a battle of clashing horns.", "674": "It grows up imitating the behavior of Pangoro, which it looks up to as a leader.", "675": "This Pokémon boasts great physical strength. Many Trainers are also smitten by its lively character.", "676": "Historically, in the Kalos region, these Pokémon were the designated guardians of the king.", "677": "The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.", "678": "When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck to dust.", "679": "It is born when a departed spirit inhabits a sword. It attaches to people and drinks their life force.", "680": "The complex attack patterns of its two swords are unstoppable, even for an accomplished opponent.", "681": "It can detect the innate qualities of leadership. Whoever it recognizes is destined to become king.", "682": "It emits a scent that delights those who smell it. The fragrance changes depending on what it has eaten.", "683": "It devises various scents and emits scents that its enemies dislike in order to gain an edge in battle.", "684": "Because it eats nothing but sweets, its fur is as sticky sweet as cotton candy.", "685": "It can distinguish the faintest of scents. It puts its sense of smell to use by helping pastry chefs.", "686": "It draws prey near with its blinking lights and then wraps them up in its long tentacles.", "687": "It wields the most compelling hypnotic powers of any Pokémon, and it forces others to do anything.", "688": "Two Binacle live together on one rock. When they fight, one of them will move to a different rock.", "689": "When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.", "690": "It looks just like rotten kelp. It hides from foes while storing up power for its evolution.", "691": "Tales are told of ships that wander into seas where Dragalge live, never to return.", "692": "They knock down flying prey by firing compressed water from their massive claws like shooting a pistol.", "693": "Their enormous claws launch cannonballs of water powerful enough to pierce tanker hulls.", "694": "The frills on either side of its head have cells that generate electricity when exposed to sunlight.", "695": "It flares its frill and generates energy. It can generate sufficient electricity to power a skyscraper.", "696": "Its immense jaws have enough destructive force to chew up an automobile. It lived 100 million years ago.", "697": "Nothing could stop this Pokémon 100 million years ago, so it behaved like a king.", "698": "This calm Pokémon lived in a cold land where there were no violent predators like Tyrantrum.", "699": "This usually quiet and kindly Pokémon has a surface temperature of around -240 degrees Fahrenheit.", "700": "It sends a soothing aura from its ribbonlike feelers to calm fights.", "701": "Although its body is small, its proficient fighting skills enable it to keep up with big bruisers.", "702": "Its upper whiskers are sensors that survey its surroundings. Its lower whiskers shoot electricity.", "703": "Born from temperatures and pressures deep underground, it fires beams from the stone in its head.", "704": "It's covered in a slimy membrane that makes any punches or kicks slide off it harmlessly.", "705": "It crawls along sluggishly. The swirly protrusion on its back is filled with its brain and other organs.", "706": "An amazingly friendly Pokémon, but if left to itself, loneliness overcomes it, and it oozes gooey tears.", "707": "These key collectors threaten any attackers by fiercely jingling their keys at them.", "708": "It is created when a spirit possesses rotten tree stumps. It prefers to live in abandoned forests.", "709": "It can control trees at will. It will trap people who harm the forest, so they can never leave.", "710": "It is said to carry wandering spirits to the place where they belong so they can move on.", "711": "It enwraps its prey in its hairlike arms. It sings joyfully as it observes the suffering of its prey.", "712": "It blocks opponents' attacks with the ice that shields its body. It uses cold air to repair any crack.", "713": "The way several Bergmite huddle on its back make it look like an aircraft carrier made of ice.", "714": "They live in pitch black caves. Their enormous ears can emit ultrasonic waves of 200,000 hertz.", "715": "This hot-blooded Pokémon attacks anything it sees with ultrasonic waves that can crush boulders.", "716": "When the horns on its head shine in seven different colors, it is said to be sharing everlasting life.", "717": "When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon.", "718": "When the Kalos region's ecosystem falls into disarray, it appears and reveals its secret power.", "719": "It can instantly create many diamonds by compressing the carbon in the air between its hands.", "720": "It gathers things it likes and passes them through its loop to teleport them to a secret place.", "721": "It expels its internal steam from the arms on its back. It has enough power to blow away a mountain.", "722": "It feels relaxed in tight, dark places and has been known to use its Trainer's pocket or bag as a nest.", "723": "It throws sharp feathers called blade quills at enemies or prey. It seldom misses.", "724": "Although basically cool and cautious, when it's caught by surprise, it's seized by panic.", "725": "It doesn't allow its emotions to be easily seen. Earning its trust takes time. It prefers solitude.", "726": "It boasts powerful front legs. With a single punch, it can bend an iron bar right over.", "727": "When its fighting spirit is set alight, the flames around its waist become especially intense.", "728": "The balloons it inflates with its nose grow larger and larger as it practices day by day.", "729": "It attacks by smacking its enemies with the exploding water balloons that it creates.", "730": "To Primarina, every battle is a stage. It takes down its prey with beautiful singing and dancing.", "731": "It may look spindly, but its neck muscles are heavy-duty. It can peck at a tree 16 times per second!", "732": "It can bend the tip of its beak to produce over a hundred different cries at will.", "733": "Known for forming harmonious couples, it is brought to wedding ceremonies as a good luck charm.", "734": "It prefers to eat fresh living things so it marches down streets in search of prey.", "735": "Patient by nature, it loses control of itself and pounces when it spots its favorite meal-Rattata!", "736": "Its strong jaw enables it to scrape trees and slurp out the sap. It normally lives underground.", "737": "From the food it digests, it generates electricity, and it stores this energy in its electric sac.", "738": "It flusters opponents with acrobatic flying maneuvers. This creates an opening for it to attack.", "739": "Its hard pincers are well suited to both offense and defense.", "740": "It stores coldness in its pincers and pummels its foes. It can even smash thick walls of ice to bits!", "741": "This Oricorio has sipped red nectar. Its passionate dance moves cause its enemies to combust in both body and mind.", "742": "Myriads of Cutiefly flutter above the heads of people who have auras resembling those of flowers.", "743": "Some of Ribombee's pollen puffs are highly nutritious. They are sometimes sold as supplements.", "744": "When it rubs the rocks on its neck against you, that's proof of its love for you.", "745": "Well equipped with claws and fangs, it uses the sharp rocks in its mane as weapons.", "746": "They're weak, so they move in schools. However, they can also often be seen all alone, having strayed from the school.", "747": "Aside from its head, its body parts regenerate quickly if they're cut off.", "748": "It crawls along the ocean floor on its 12 legs. It leaves a trail of Corsola bits scattered in its wake.", "749": "The mud stuck to Mudbray's hooves enhances its grip and its powerful running gait.", "750": "It can trudge mountain roads without rest for three days, all the while dragging a 10-ton load.", "751": "It crawls onto the land in search of food. Its water bubble allows it to breathe and protects its head.", "752": "It delivers headbutts with the bubble on its head. Small Pokémon get sucked into it, where they drown.", "753": "It loves the sunshine. When it basks in the sunlight regularly, it grows up with vivid coloration.", "754": "For self-protection, it pretends to be a bug Pokémon. Both of its arms bear keen-edged petals.", "755": "It scatters spores that flicker and glow. Anyone seeing these lights falls into a deep slumber.", "756": "When it starts fighting for territory with Parasect, the entire area gets completely coated in spores!", "757": "It burns its bodily fluids to create a poisonous gas. It weakens enemies and sends them reeling with it.", "758": "It punishes Salandit that couldn't bring it food with a fierce slap of its flame-spewing palm.", "759": "Stufful hates to be hugged or touched in any way. It will squirm, thrash, and resist with amazing power.", "760": "It boasts tremendous physical strength. Many people call it the most dangerous Pokémon in Alola region.", "761": "Because of its sweet, delicious aroma, bird Pokémon are always after it.", "762": "It bounces around, swinging the sepals on its head with abandon. It's quite painful when it smacks you!", "763": "A master of grand and beautiful kicks, it can knock out even kickboxing champions with a single blow.", "764": "Baths prepared with the flowers from its vine have a relaxing effect so it is a hit to many people.", "765": "Known for its extreme intelligence, it will look down on inexperienced Trainers.", "766": "They form groups of 20 individuals. Their mutual bond is remarkable-they will never let down a comrade.", "767": "An astonishingly cowardly Pokémon, it whirs its legs at high speed to run away if anything comes near it.", "768": "With a flashing slash of its giant sharp claws, it cleaves seawater-or even air-right in two.", "769": "Born from a sand mound playfully built by a child, this Pokémon embodies the grudges of the departed.", "770": "Buried beneath the castle are masses of dried-up bones from those whose vitality it has drained.", "771": "Its body is covered with slime. If you accidentally step on it, you'll slip, and it will get mad at you!", "772": "There's danger of its going on a rampage, so its true power is sealed away beneath its control mask.", "773": "It destroyed its own control mask. It has become capable of changing type by equipping special memories.", "774": "It eats dust in the atmosphere. The composition of the dust determines the color of its core.", "775": "It stays asleep from the moment it's born. When it falls into a deep sleep, it stops moving altogether.", "776": "It gushes fire and poisonous gases from its nostrils. Its dung is an explosive substance.", "777": "When it's surprised or agitated, the 14 fur spikes on its back will stand up involuntarily.", "778": "It conceals its terrifying appearance beneath an old rag so it can get closer to people and Pokémon.", "779": "Its skin is thick enough to fend off spikes. With its robust teeth, it crunches up and eats the spikes.", "780": "It appears in towns and plays with the children. Drampa will protect kids when they're in danger.", "781": "It wraps its prey in green seaweed and sucks away their vitality. It only likes to go after big prey.", "782": "They live in mountains where no trace of humans can be detected. It grows as it battles others.", "783": "It leaps at its prey with a courageous shout. Its scaly punches tear its opponents to shreds.", "784": "It battles valiantly with its fists, which are armored in steel scales. Kommo-o specializes in uppercuts.", "785": "This guardian deity of Melemele summons thunderclouds and stores their lightning inside its body.", "786": "This guardian deity of Akala is guilelessly cruel. Its flowers' fragrant aroma is its source of energy.", "787": "The guardian deity of Ula'ula is a lazy Pokémon. It commands plants to immobilize its foes.", "788": "The guardian deity of Poni can control water. It can create pure water that will wash away any impurity.", "789": "Its body is gaseous and frail. It slowly grows as it collects dust from the atmosphere.", "790": "As it absorbs light, Cosmoem continues to grow. Its golden shell is surprisingly solid.", "791": "In writings from the distant past, it's called by the name \"the beast that devours the sun.\"", "792": "It sometimes summons unknown powers and life-forms to this world from holes that lead to other worlds.", "793": "A life-form from another world, it was dubbed a UB and is thought to produce a strong neurotoxin.", "794": "Buzzwole goes around showing off its abnormally swollen muscles. It is one kind of Ultra Beast.", "795": "One of the dangerous Ultra Beasts, it has been spotted running across the land at terrific speeds.", "796": "It appeared from the Ultra Wormhole. It raided a power plant, so it energizes itself with electricity.", "797": "It appeared from the Ultra Wormhole. Witnesses observed it flying across the sky at high speed.", "798": "This Ultra Beast's body, which is as thin as paper, is like a sharpened sword.", "799": "An unknown life-form called a UB. It may be constantly hungry-it is certainly always devouring something.", "800": "Light is the source of its energy. If it isn't devouring light, impurities build up in it.", "801": "Its mechanized body is merely a vessel. Its true self is its Soul-Heart, an artificial soul.", "802": "It lurks in the shadows of others, copying their movements and powers. It is craven and cowering.", "803": "This Ultra Beast is well enough liked to be chosen as a first partner in its own world.", "804": "It stores hundreds of liters of poisonous liquid in its body. It is one of the organisms known as UBs.", "805": "When stone walls started moving and attacking, the brute's true identity was this mysterious life-form.", "806": "It causes explosions, then takes advantage of opponents' surprise to rob them of their vitality.", "807": "It approaches its enemies at the speed of lightning, then tears them limb from limb with its sharp claws.", "808": "It melts particles of iron and other metals found in the subsoil, so it can absorb them into its molten steel body.", "809": "Revered long ago for its capacity to create iron from nothing, it has come back to life after 3000 years.", "810": "It attacks with rapid beats of its stick. As it strikes with amazing speed, it gets more and more pumped.", "811": "The faster a Thwackey can beat out a rhythm with its two sticks, the more respect it wins from its peers.", "812": "By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.", "813": "It has special pads on the backs of its feet, and one on its nose. Its pads radiate tremendous heat.", "814": "Its thick and fluffy fur protects it from the cold and enables it to use hotter fire moves.", "815": "It gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.", "816": "When it gets wet, its skin changes color, and this Pokémon becomes invisible as if it were camouflaged.", "817": "Highly intelligent but also very lazy, it keeps enemies out of its territory by laying traps everywhere.", "818": "It picks out foes' weak points so it can precisely blast them with water that shoots from its fingertips.", "819": "This Pokémon becomes uneasy if its cheeks are ever completely empty of berries.", "820": "This Pokémon has strong teeth and can chew through the toughest of berry shells.", "821": "It will bravely challenge any foe, no matter how powerful. Even suffering a defeat increases its strength a bit.", "822": "The lessons of many harsh battles have taught it how to accurately judge an opponent's strength.", "823": "The black luster of its steel body could drive terror into the heart of any foe.", "824": "A constant collector of information, this Pokémon is very smart. Very strong is what it isn't.", "825": "As it grows inside its shell, it uses its psychic abilities to monitor its surroundings and wait for evolution.", "826": "It's famous for its high intelligence, and the large size of its brain is proof that it has immense psychic power.", "827": "Aided by the soft pads on its feet, it silently raids the food stores of others. It survives off its ill-gotten gains.", "828": "With a lithe body and sharp claws, it goes around stealing food and eggs. It secretly marks its future targets.", "829": "It anchors itself in the ground and basks in the sun. After absorbing enough sunlight, it blooms vividly.", "830": "The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that others can benefit.", "831": "If its fleece grows too long, it won't be able to move. Cloth made with its wool is surprisingly durable.", "832": "Its majestic horns are meant only to impress the opposite gender. They never see use in battle.", "833": "Apparently the itch of its teething impels it to snap its jaws at anything in front of it.", "834": "With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.", "835": "This greedy Pokémon only helps people with their work because it wants treats. As it runs, it crackles with electricity.", "836": "It sends electricity through its legs to boost their strength. Running at top speed, it easily breaks 50 mph.", "837": "It can race around like a unicycle, even on rough, rocky terrain. Burning coal sustains it.", "838": "By rapidly rolling its legs, it can easily travel at over 18 mph. It forms coal inside its body.", "839": "While engaged in battle, its mountain of coal will burn bright red, scorching the surrounding area with sparks.", "840": "As soon as it's born, it burrows into an apple. The flavor of the apple is what determines its evolution.", "841": "It ate a sour apple, which induced its evolution. It stores an acid capable of causing chemical burns in its cheeks.", "842": "It ate a sweet apple, which induced its evolution. Back in the day, children used to have it as a snack.", "843": "It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.", "844": "When it contracts its body, over 220 pounds of sand sprays from its nose. It becomes disheartened if it runs out.", "845": "This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow other Pokémon.", "846": "It becomes extremely sluggish after eating its fill. That's when Cramorant swallows it up.", "847": "Its jaw is as sharp as a spear and as strong as steel. It spins its tail fins to surge forward at over 100 knots.", "848": "It manipulates the chemical makeup of its poison to produce electricity. Despite a weak voltage, it can cause paralysis.", "849": "This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.", "850": "It stores flammable gas in its body and uses it to generate heat. It then coils around its prey and cooks it.", "851": "This excessively hostile Pokémon has large and very sharp fangs in addition to its dangerous burning body.", "852": "It's very curious, but its means of investigating things is to try to punch them with its tentacles.", "853": "Searching for an opponent to test its skills against, it emerges onto land. Once the battle is over, it returns to the sea.", "854": "This Pokémon is said to have been born when a lonely spirit possessed a cold, leftover cup of tea.", "855": "This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.", "856": "Via the protrusion on its head, it senses other creatures' emotions. It prefers areas without people.", "857": "No matter who you are, if you bring strong emotions near this Pokémon, it will silence you violently.", "858": "Known as the Forest Witch, if you are too loud around it, you risk being torn apart by the claws on its tentacle.", "859": "It sneaks into people's homes, taking and feasting on the negative energy of the frustrated occupants.", "860": "With sly cunning, it lures people into the woods. Some believe it to have the power to make crops grow.", "861": "Its hairs work like muscle fibers. When its hairs unfurl, they latch on to foes, ensnaring them like tentacles.", "862": "It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that'd make anyone flinch.", "863": "What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.", "864": "Be cautious of the ectoplasmic body surrounding its soul. You'll become stiff as stone if you touch it.", "865": "After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk.", "866": "Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.", "867": "Never touch its shadowlike body, or you'll be shown the horrific memories behind the picture carved into it.", "868": "They say that any patisserie visited by Milcery is guaranteed success and good fortune.", "869": "It evolved from a Milcery that held onto a Strawberry Sweet. Its flavor depends on how it was mixed.", "870": "The six of them work together as one. Teamwork is also their battle strategy, and they constantly change formation.", "871": "It feeds on seaweed, using its teeth to scrape it off rocks. Electric current flows from the tips of its spines.", "872": "It eats snow that piles up on the ground. The more snow it eats, the bigger its spikes grow.", "873": "Icy scales fall from its wings like snow as it flies over fields and mountains.", "874": "Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle.", "875": "It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to stay cold.", "876": "Through its horns, it can pick up on the emotions of creatures around it. Males will act as valets for those they serve.", "877": "As it eats the seeds stored up in its pouches, it generates electricity while satisfying its constant hunger.", "878": "If a job requires serious strength, Cufant will excel at it. Its copper body tarnishes in the rain, turning green.", "879": "These Pokémon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks.", "880": "The powerful muscles in its tail generate its electricity. Its upper half is entirely too small.", "881": "The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.", "882": "Its mighty legs are capable of running at speeds exceeding 40 mph, but it can't breathe unless it's underwater.", "883": "The skin on its face is impervious to attack, but breathing difficulties made it go extinct anyway.", "884": "Its body resembles polished metal, and it's both lightweight and strong. However, its body rusts easily.", "885": "After being reborn as a ghost, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.", "886": "It's capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they evolve.", "887": "Apparently the Dreepy inside its horns eagerly look forward to being launched out at Mach speeds.", "888": "It has slumbered for many years. Some say it is Zamazenta's elder sister, others say the two are rivals.", "889": "It slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed.", "890": "It was inside a meteorite that fell 20,000 years ago. The energy that its core absorbs allows it to live. #org @DEX_ENTRY_KUBFU If it pulls the long white hair on its head, its fighting spirit heightens and power wells up from deep in its belly.", "892": "Inhabiting the mountains of a distant region, it races across sheer cliffs, training its legs and refining its moves.", "893": "Once the vines on its body tear off, they become nutrients in the soil. This helps the plants of the forest grow.", "894": "Its entire body is made of an organ that generates electricity. It is capable of generating a region's worth of electricity.", "895": "Its body is composed of crystallized dragon energy. It is said to contain the power of every Dragon Pokémon.", "896": "Glastrier has tremendous physical strength. The mask covering its face is 100 times stronger than diamond.", "897": "As it dashes through the night, it absorbs the life energy of sleeping Pokémon. It craves silence and solitude.", "898": "Its every move is filled with grace and dignity. Extremely intelligent, it is said to see past, present, and future events.", "899": "The fur shed from its beard retains heat well and is a highly useful material for winter clothing.", "900": "A violent creature that fells towering trees with its crude axes and shields itself with hard stone.", "901": "Swampy terrain gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.", "902": "It clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream.", "903": "It has virulent poison and daunting physical prowess. Preferring solitude, this species does not form packs.", "904": "Its lancelike spikes and savage temperament have earned it the nickname \"sea fiend.\"", "905": "According to legend, this Pokémon's love gives rise to the budding of fresh life across the land.", "906": "Its fluffy fur is similar in composition to plants. It washes its face frequently to prevent dryness.", "907": "It deftly wields the hard flower bud from the vine hidden beneath its long fur towards its opponents.", "908": "It makes the flower appear to be floating by hiding the stem with the reflecting fur covering its cape.", "909": "It lies on warm rocks and uses the heat absorbed by its square-shaped scales to create fire energy.", "910": "Its fire energy and overflowing vitality have combined to create an egg-shaped fireball on its head.", "911": "Rumor has it that the bird was born when the fireball on Skeledirge's head gained a soul.", "912": "This Pokémon migrated to Paldea from distant lands long ago. It likes order and tends to overthink things.", "913": "It observes people and Pokémon from various regions and integrates their movements into its dance routines.", "914": "This Pokémon uses its powerful legs to perform striking dances from far-off lands.", "915": "It searches for food all day. Its body gives off an herblike scent that bug Pokémon detest.", "916": "It entrances female Pokémon with the sweet, alluring scent that wafts from all over its body.", "917": "Its body is covered in a ball of threads that is elastic enough to deflect Scyther's scythes.", "918": "Spidops covers its territory in tough, sticky threads to set up traps for intruders.", "919": "When it's in a tough spot, this Pokémon jumps over 30 feet using the strength of its legs.", "920": "When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode.", "921": "Its sacs can produce electricity only if Pawmi rubs them furiously with the pads on its forepaws.", "922": "Pawmo uses its forepaws to strike foes and zap them with electricity from its paw pads simultaneously.", "923": "Pawmot's fluffy fur can store the same amount of electricity as an electric car.", "924": "Exhibiting great teamwork, they split any food they find exactly in half and then eat it together.", "925": "They build huge nests with many rooms for different purposes, such as eating and sleeping.", "926": "This Pokémon is smooth and moist to the touch. Fidough's breath is also useful for cooking.", "927": "This Pokémon's body has a luring aroma, and its skin surface hardens when exposed to intense heat.", "928": "This Pokémon converts nutrients into oil, which it stores in the fruit on its head.", "929": "Dolliv shares its tasty, fragrant oil with others. Since long ago, this species has coexisted with humans.", "930": "This calm Pokémon is incredibly kind. It shares its delicious, nutrient- rich oil with weakened Pokémon.", "931": "These Pokémon prefer to live in cities. When they're out searching for food, it gets very noisy.", "932": "This Pokémon was particularly treasured in the old days, as they would share precious salt.", "933": "It compresses and shoots out hardened salt pellets with enough force to perforate an iron sheet.", "934": "Many Pokémon gather around Garganacl, hoping to lick at its mineral-rich salt.", "935": "Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.", "936": "Armarouge evolved through the use of a set of armor that belonged to a distinguished warrior.", "937": "The fiercely burning blades on its arms can cut its enemies to pieces without mercy.", "938": "Tadbulb shakes its tail to generate electricity. It floats using the electricity stored in its body.", "939": "The eyeballs are actually organs for releasing the electricity generated by Bellibolt's belly-button dynamo.", "940": "It builds its nests on coastal cliffs. When its wings catch the wind, the bones within produce electricity.", "941": "Kilowattrel inflates its throat sac to amplify its electricity. It can fly over 430 miles in a day.", "942": "Its jaw and fangs are strong enough to crunch through boulders, and its thick fat makes a superb defense.", "943": "Though usually gentle, Mabosstiff takes on an intimidating look when protecting its family.", "944": "It will sink its sharp, poison-soaked front teeth into any that anger it, paralyzing them.", "945": "Each Grafaiai paints its own individual pattern that it will repeatedly paint throughout its life.", "946": "Not even Bramblin knows where it is headed as it tumbles across the wilderness, blown by the wind.", "947": "Once Brambleghast absorbs all the life energy it needs, it expels the prey and discards it.", "948": "Toedscool lives in muggy forests. The flaps that fall from its body are chewy and very delicious.", "949": "It coils its 10 tentacles around prey and sucks out their nutrients, causing the prey pain.", "950": "It lives on sheer cliffs. It dodges opponents' attacks before lunging with its claws at their weak spots.", "951": "The more sunlight this Pokémon bathes in, the more spicy chemicals are produced by its body.", "952": "The green head has turned vicious due to the spicy chemicals stimulating its brain.", "953": "This Pokémon rolls its mud ball around while the energy it needs for evolution matures.", "954": "Rabsca rolls the ball soothingly with its legs to ensure the infant inside the ball sleeps comfortably.", "955": "If anyone steals its beloved berries, Flittle will chase them down and exact its revenge.", "956": "It immobilizes opponents by bathing them in psychic power from its large eyes.", "957": "It swings its hammer around to guards itself, but the hammer is often stolen by Pokémon that eat metal.", "958": "It will attack groups of Pawniard and Bisharp, gathering metal from them to make a large, sturdy hammer.", "959": "It knocks rocks into the sky with its hammer, aiming for flying Corviknight.", "960": "It can pick up the scent of a Veluza just over 65 feet away and will hide itself in the sand.", "961": "A variety of fish Pokémon, Wugtrio was once considered to be a regional form of Dugtrio.", "962": "Bombirdier uses the apron on its chest to bundle up food, which it carries back to its nest.", "963": "Its water ring is made from seawater mixed with a sticky fluid that Finizen secretes from its blowhole.", "964": "This Pokémon changes its appearance if it hears its allies calling for help.", "965": "This Pokémon clings to rocks and converts the minerals within into energy to fuel its activities.", "966": "It sticks its tongue out from its cylindrical mouth and sprays toxic fluids.", "967": "Apparently, Cyclizar has been allowing people to ride on its back since ancient times.", "968": "This Pokémon lives in arid deserts. It maintains its metal body by consuming iron from the soil.", "969": "It absorbs nutrients from cave walls. The petals it wears are made of crystallized poison.", "970": "When Glimmora senses danger, it will open up its crystalline petals and fire beams from its conical body.", "971": "A dog Pokémon that died in the wild without ever interacting with a human was reborn as this Pokémon.", "972": "A lovingly mourned Pokémon was reborn as Houndstone. It sleeps in graveyards most of the time.", "973": "It ties the base of its neck into a knot so that energy stored in its belly does not escape from its beak.", "974": "It lives in frigid regions in pods of five or so individuals. It loves the minerals found in snow and ice.", "975": "It protects its body with powerful muscles and a thick layer of fat under its skin.", "976": "It sheds spare flesh from its body to boost its agility, then charges at its prey.", "977": "It treats Tatsugiri like its boss and follows it loyally. Though powerful, Dondozo is not very smart.", "978": "This is a small dragon Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.", "979": "This Pokémon imbues its fists with the power of the rage that it kept hidden in its heart.", "980": "It will carry Wooper on its back and ferry them across water from one shore to the other.", "981": "When the head from its tail closes its mouth, Farigiraf whips its long neck around to headbutt enemies.", "982": "This Pokémon uses its hard tail to make its nest by boring holes into bedrock deep underground.", "983": "Only a Bisharp that stands above all others in its vast army can evolve into Kingambit.", "984": "This creature resembles a mysterious Pokémon that has lived since ancient times.", "985": "It resembles a mysterious Pokémon described as a Jigglypuff from one billion years ago.", "986": "It bears a slight resemblance to a Pokémon described as a cross between a dinosaur and a mushroom.", "987": "This Pokémon has similar features to a ghostly pterosaur that was covered in a certain book.", "988": "This Pokémon somewhat resembles an ancient form of Volcarona that was introduced in a dubious magazine.", "989": "It slightly resembles a Magneton that lived for 10,000 years and was introduced in a paranormal magazine.", "990": "This Pokémon resembles a scientific weapon that a paranormal magazine claimed was sent to Earth by aliens.", "991": "Its shape is similar to a robot. The robot was said to have been created by an ancient civilization.", "992": "It is very similar to a cyborg. The cyborg was said to be the modified form of a certain athlete.", "993": "This Pokémon described as the offspring of a Hydreigon that fell in love with a robot.", "994": "This Pokémon resembles an unknown object described as a UFO sent to observe humanity.", "995": "It resembles a mysterious Pokémon described as a Tyranitar from one billion years into the future.", "996": "This Pokémon lives in forests and craggy areas. It cools the inside of its nest using its dorsal fin.", "997": "Arctibax protects its face with an ice mask and turning its dorsal fin into a blade of ice.", "998": "This Pokémon blasts cryogenic air out from its mouth. It finishes enemies off with its dorsal blade.", "999": "Sometimes Gimmighoul gets left in shop corners since no one realizes it's actually a Pokémon.", "1000": "Its body seems to be made up of 1,000 coins. This Pokémon is quick to make friends with anybody.", "1001": "It drains vegetation's life-force, causing nearby forests and fields quickly going to seedlessness.", "1002": "The hatred of those who perished by the sword long ago has clad itself in snow and become a Pokémon.", "1003": "The fear poured into an ancient ritual vessel has clad itself in rocks and dirt to become a Pokémon.", "1004": "It casually swims through the sea of lava it creates by melting rock and sand.", "1005": "This Pokémon has some connection to a phenomenon that occurs in a certain region.", "1006": "It has some similarities to a mad scientist's invention covered in a paranormal magazine.", "1007": "It was said to have split the land with its bare fists. Its ecology or other features are unknown.", "1008": "Much remains unknown about this creature. It is said to have turned the land to ash with its lightning.", "1009": "This mysterious creature appears to be an ancient relative of the legendary Pokémon Suicune.", "1010": "This mysterious creature appears to be a futuristic relative of the legendary Pokémon Virizion.", "1011": "Dipplin is two creatures in one Pokémon. Its evolution was triggered by a special apple grown only in one place.", "1012": "It sprinkles some of its powdery body onto food and drains the life-force from those who so much as lick it.", "1013": "It pretends to be tea, trying to fool people into drinking it so it can drain their life-force.", "1014": "Okidogi is a ruffian with a short temper. It can pulverize anything by swinging around its chain.", "1015": "Munkidori keeps itself somewhere safe while it toys with its foes, using psychokinesis to induce dizziness.", "1016": "Fezandipiti beats its glossy wings to scatter pheromones that captivate people and Pokémon.", "1017": "This Pokémon's type changes based on which mask it's wearing. It confounds its enemies with nimble movements.", "1018": "It gathers static electricity from its surroundings. The beams it launches are tremendously powerful.", "1019": "Seven syrpents live inside an apple made of syrup. The syrpent in the center is the commander.", "1020": "There are scant few reports of this creature being sighted. It's said to rampage and spout pillars of flame.", "1021": "It's said to incinerate everything around it with lightning launched from its fur.", "1022": "It was named after a mysterious object recorded in an old book. Its body seems to be metallic.", "1023": "There was supposedly an incident in which it launched shining blades to cut everything around it to pieces.", "1024": "It's thought that this Pokémon lived long ago until it got caught in seismic shifts and went extinct.", "1025": "It feeds others toxic mochi that draw out desires and capabilities and chain them to its will. //Special Form Entries"};   // national number -> text. Only the entries your DPE strings file has (the old ones live in the ROM, not in a file). Add more yourself: DexText[25] = "...";


// ---------------------------------------------------------------------------- the Pokedex of the player: GameStateManager.saveData.dex = { seen: {25: 1}, caught: {25: 1} }
const Dex = {
  num(species) { if (species == null) return 0; if (typeof species === 'number') return species; return SpeciesToDex[String(species).replace(/^SPECIES_/, '').replace(/_/g, '')] || 0; },
  entry(n) { const r = DexEntries[n - 1]; return r ? { num: r[0], name: r[1], category: r[2], height: r[3], weight: r[4], species: r[5], textKey: r[6] } : null; },
  text(n) { const e = this.entry(n); if (!e) return ''; return String(DexText[n] || DexText[e.name] || DexText[e.textKey] || '').trim(); },
  data() { const s = window.GameStateManager && window.GameStateManager.saveData; if (!s) return { seen: {}, caught: {}, shiny: {} }; const d = s.dex || (s.dex = { seen: {}, caught: {}, shiny: {} }); d.seen = d.seen || {}; d.caught = d.caught || {}; d.shiny = d.shiny || {}; return d; },
  see(species) { const n = this.num(species); if (!n) return false; const d = this.data(); if (d.seen[n]) return false; d.seen[n] = 1; if (window.SaveSystem) window.SaveSystem.touch(); return true; },
  catch(species, shiny) { const n = this.num(species); if (!n) return false; const d = this.data(), fresh = !d.caught[n] || (shiny && !d.shiny[n]); d.seen[n] = 1; d.caught[n] = 1; if (shiny) d.shiny[n] = 1; if (fresh && window.SaveSystem) window.SaveSystem.touch(); return fresh; },
  seen(n) { return !!this.data().seen[n]; }, caught(n) { return !!this.data().caught[n]; }, shiny(n) { return !!this.data().shiny[n]; },
  counts() { const d = this.data(); return { seen: Object.keys(d.seen).length, caught: Object.keys(d.caught).length, shiny: Object.keys(d.shiny).length, total: DexEntries.length }; },
  order(mode) { return mode === 'national' || !DexOrders[mode] ? DexEntries.map(r => r[0]) : DexOrders[mode]; },
};
window.DexEntries = DexEntries; window.SpeciesToDex = SpeciesToDex; window.DexOrders = DexOrders; window.DexText = DexText; window.Dex = Dex;
